import React, {useCallback, useMemo} from 'react';

import {Icon, Text} from '@gravity-ui/uikit';

import {TrackerDisclosure} from '../../TrackerDisclosure/TrackerDisclosure';
import {cnTrackerSelect} from '../TrackerSelect.classname';
import type {TrackerSelectGroup, TrackerSelectItem, TrackerSelectItemValueBase} from '../types';

import {SelectItems} from './SelectItems';

export type SelectGroupProps<
    Value extends TrackerSelectItemValueBase = TrackerSelectItemValueBase,
> = {
    group: TrackerSelectGroup<Value>;
    items: TrackerSelectItem<Value>[];
    selectedItemsIds?: string[];
    disabledItemsIds?: string[];
    onItemClick?: (item: TrackerSelectItem<Value>) => void;
    onItemPin?: (id: string) => void;
    onItemUnpin?: (id: string) => void;
    activeItemId?: string;
    expanded?: boolean;
    onExpandChange?: (groupId: string, expanded: boolean) => void;
    className?: string;
    groupId?: string;
    collapsible?: boolean;
    withHeading?: boolean;
} & Pick<
    Parameters<typeof SelectItems>[0],
    | 'renderItem'
    | 'renderInfo'
    | 'showArrowOnUnselectedItems'
    | 'hideCheckbox'
    | 'singleSelect'
    | 'showMeta'
    | 'itemActions'
    | 'pinnable'
    | 'disableDefaultItemRender'
    | 'itemClassName'
>;

export const SelectGroup = <Value extends TrackerSelectItemValueBase>({
    group,
    items,
    selectedItemsIds,
    disabledItemsIds,
    onItemClick,
    onItemPin,
    onItemUnpin,
    activeItemId,
    expanded,
    onExpandChange,
    renderItem,
    renderInfo,
    showArrowOnUnselectedItems,
    hideCheckbox,
    singleSelect,
    showMeta,
    itemActions,
    pinnable,
    disableDefaultItemRender,
    itemClassName,
    className,
    groupId,
    collapsible,
    withHeading,
}: SelectGroupProps<Value>) => {
    const handleExpandChange = useCallback(
        (newExpanded: boolean) => {
            onExpandChange?.(group.id, newExpanded);
        },
        [group.id, onExpandChange],
    );

    const modifiers = useMemo(() => {
        const mods: Record<string, boolean | string> = {};
        if (group.type) {
            mods.type = group.type;
        }
        return mods;
    }, [group.type]);

    const renderSelectedItems = () => (
        <SelectItems
            items={items}
            selectedItemsIds={selectedItemsIds}
            disabledItemsIds={disabledItemsIds}
            onItemClick={onItemClick}
            onItemPin={onItemPin}
            onItemUnpin={onItemUnpin}
            activeItemId={activeItemId}
            renderItem={renderItem}
            renderInfo={renderInfo}
            showArrowOnUnselectedItems={showArrowOnUnselectedItems}
            hideCheckbox={hideCheckbox}
            singleSelect={singleSelect}
            showMeta={showMeta}
            itemActions={itemActions}
            pinnable={pinnable}
            disableDefaultItemRender={disableDefaultItemRender}
            itemClassName={itemClassName}
            groupId={groupId}
        />
    );

    if (collapsible) {
        return (
            <div className={cnTrackerSelect('group', modifiers, className)}>
                <TrackerDisclosure
                    key={group.id}
                    summary={
                        <span
                            data-id={`group-${group.id}`}
                            className={cnTrackerSelect('collapse-group-title')}
                        >
                            {group.icon && <Icon data={group.icon} size={16} />}
                            <span>{group.name ?? ''}</span>
                        </span>
                    }
                    className={cnTrackerSelect('collapse')}
                    summaryClassName={cnTrackerSelect('collapse-header')}
                    arrowClassName={cnTrackerSelect('collapse-header-icon')}
                    defaultExpanded={group.expand}
                    expanded={expanded}
                    onUpdate={handleExpandChange}
                >
                    {(group.expand || expanded) && renderSelectedItems()}
                </TrackerDisclosure>
            </div>
        );
    }

    return (
        <div className={cnTrackerSelect('group', modifiers, className)}>
            {withHeading ? (
                <Text as="h2" variant="body-1" className={cnTrackerSelect('group-title')}>
                    {group.name}
                </Text>
            ) : null}
            {renderSelectedItems()}
        </div>
    );
};
